\title{An Elementary Structural Theory of Taxicab Representations}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
A \emph{taxicab representation} of a natural number $N$ is an ordered pair $(a,b)$ of positive integers with $a \le b$ and $a^3 + b^3 = N$; the $n$-th taxicab number $\mathrm{Taxicab}(n)$ is the least $N$ admitting at least $n$ distinct such representations. Named for the Hardy--Ramanujan number $1729 = 1^3 + 12^3 = 9^3 + 10^3$, these numbers sit at the crossroads of elementary number theory and the deep arithmetic of elliptic curves. We develop a self-contained elementary theory: a representation is completely determined by its smaller summand, whence an unconditional cubic lower bound $\mathrm{Taxicab}(n) > n^3$ follows by pigeonhole; multiplication by a perfect cube transports representations injectively, so representation counts never decrease under cube multiplication. We verify the classical champions $1729$, $87{,}539{,}319$, and $6{,}963{,}472{,}309{,}248$ as sums of two positive cubes in $2$, $3$, and $4$ genuinely distinct ways, and we delineate precisely the boundary where the arithmetic of the Fermat cubic elliptic curve becomes indispensable.
\end{abstract}

\maketitle

\section{Introduction}

The number $1729$ owes its fame to a bedside exchange between G.~H.~Hardy and Srinivasa Ramanujan: it is the smallest positive integer expressible as a sum of two positive cubes in two distinct ways,
\[
1729 = 1^3 + 12^3 = 9^3 + 10^3.
\]
Generalizing, for each positive integer $n$ one asks for the least positive integer expressible as a sum of two positive cubes in $n$ distinct ways; this quantity, when it exists, is the \emph{$n$-th taxicab number} $\mathrm{Taxicab}(n)$.

Two questions organize the subject. First, \textbf{existence}: is $\mathrm{Taxicab}(n)$ finite for every $n$? Second, \textbf{growth}: how fast does it grow? The existence question has a known affirmative answer whose every proof invokes elliptic curves; the growth question is only partially understood. This paper isolates and rigorously establishes the elementary core of the theory.

\section{Definitions}

Throughout, $\mathbb{N} = \{0,1,2,\dots\}$.

\begin{definition}[Representation]
For $N,a,b \in \mathbb{N}$, the pair $(a,b)$ is a \emph{taxicab representation} of $N$, written $\mathrm{IsRep}(N,a,b)$, if
\[
0 < a, \qquad a \le b, \qquad a^3 + b^3 = N.
\]
\end{definition}

\begin{definition}[Representation set]
A finite $S \subseteq \mathbb{N}\times\mathbb{N}$ is a \emph{set of representations of $N$} if every $(p_1,p_2)\in S$ satisfies $\mathrm{IsRep}(N,p_1,p_2)$. Its cardinality $|S|$ counts distinct representations.
\end{definition}

\begin{definition}[Taxicab number]
For $n\ge 1$,
\[
\mathrm{Taxicab}(n) = \min\{\, N : \text{$N$ has a set of representations of cardinality } n \,\},
\]
when the minimum exists.
\end{definition}

The cardinality formulation encodes pairwise distinctness automatically: certifying $n$ representations means exhibiting a size-$n$ set all of whose members are representations.

\section{Rigidity}

\begin{theorem}[First-coordinate injectivity]\label{thm:rigid}
Let $N\in\mathbb{N}$ and let $S$ be a set of representations of $N$. Then $\pi:(a,b)\mapsto a$ is injective on $S$.
\end{theorem}

\begin{proof}
Let $p,q\in S$ with $p_1=q_1$. Then $p_1^3+p_2^3 = N = q_1^3+q_2^3$, so $p_2^3=q_2^3$. Since $x\mapsto x^3$ is strictly increasing on $\mathbb{N}$, $p_2=q_2$, hence $p=q$.
\end{proof}

\begin{corollary}
For fixed $N$, distinct representations use distinct smaller summands; the representation count equals the number of distinct smaller summands.
\end{corollary}

\section{The cubic lower bound}

\begin{theorem}[Cubic growth floor]\label{thm:floor}
Let $N,n\in\mathbb{N}$ with $n\ge 1$. If $N$ has a set of representations of cardinality $n$, then $n^3 < N$. In particular $\mathrm{Taxicab}(n) > n^3$ whenever defined.
\end{theorem}

\begin{proof}
Let $S$ be a set of representations with $|S|=n$, and $T=\pi(S)$. By Theorem~\ref{thm:rigid}, $|T|=|S|=n$. As $n\ge 1$, $T\neq\emptyset$; let $M=\max T$. Every element of $T$ is a positive integer $\le M$, so $T\subseteq\{1,\dots,M\}$ and $n=|T|\le M$. Now $M$ is the smaller summand of some $(M,b)\in S$ with $b>0$, so $N = M^3 + b^3 > M^3$. Hence $n^3 \le M^3 < N$.
\end{proof}

\begin{remark}
The bound is unconditional and elementary but far from sharp: $\mathrm{Taxicab}(2)=1729$, $\mathrm{Taxicab}(3)=87{,}539{,}319$, and $\mathrm{Taxicab}(4)=6{,}963{,}472{,}309{,}248$ exceed their floors $8$, $27$, $64$ by many orders of magnitude.
\end{remark}

\section{Cube-scaling}

\begin{theorem}[Scaling a representation]\label{thm:scale1}
Let $N,a,b,t\in\mathbb{N}$ with $t>0$. If $\mathrm{IsRep}(N,a,b)$, then $\mathrm{IsRep}(N\,t^3,\,at,\,bt)$.
\end{theorem}

\begin{proof}
$0<at$, $at\le bt$, and $(at)^3+(bt)^3=(a^3+b^3)t^3=Nt^3$.
\end{proof}

\begin{theorem}[Scaling preserves counts]\label{thm:scale2}
Let $N,t\in\mathbb{N}$ with $t>0$ and let $S$ be a set of representations of $N$. Then there is a set $S'$ of representations of $Nt^3$ with $|S'|=|S|$.
\end{theorem}

\begin{proof}
Let $S'=\{(at,bt):(a,b)\in S\}$. By Theorem~\ref{thm:scale1} each element is a representation of $Nt^3$; the map $(a,b)\mapsto(at,bt)$ is injective since $t>0$, so $|S'|=|S|$.
\end{proof}

\begin{corollary}
If $N$ has at least $k$ representations, so does $Nt^3$ for every $t\ge 1$.
\end{corollary}

\begin{discussion}
Scaling merely transports existing representations; it never creates a representation of $Nt^3$ whose smaller summand is not a multiple of $t$. Increasing the count beyond a value already achieved requires genuinely new pairs, which the multiplicative structure alone cannot supply --- exactly where the elliptic-curve input enters.
\end{discussion}

\section{Verified classical witnesses}

Each statement below exhibits a set of the stated cardinality all of whose members are representations; the listed pairs are pairwise distinct.

\begin{theorem}[$\mathrm{Taxicab}(2)$, Hardy--Ramanujan]
$\{(1,12),(9,10)\}$ is a set of two representations of $1729$:
\[
1729 = 1^3+12^3 = 9^3+10^3.
\]
\end{theorem}

\begin{theorem}[$\mathrm{Taxicab}(3)$, Leech 1957]
$\{(167,436),(228,423),(255,414)\}$ is a set of three representations of $87{,}539{,}319$:
\[
87{,}539{,}319 = 167^3+436^3 = 228^3+423^3 = 255^3+414^3.
\]
\end{theorem}

\begin{theorem}[$\mathrm{Taxicab}(4)$]
$\{(2421,19083),(5436,18948),(10200,18072),(13322,16630)\}$ is a set of four representations of $6{,}963{,}472{,}309{,}248$:
\[
6{,}963{,}472{,}309{,}248 = 2421^3+19083^3 = 5436^3+18948^3 = 10200^3+18072^3 = 13322^3+16630^3.
\]
\end{theorem}

\begin{proposition}
$4^3 = 64 < 6{,}963{,}472{,}309{,}248$, in accordance with Theorem~\ref{thm:floor}.
\end{proposition}

\section{Discussion}

\textbf{Existence is beyond the elementary toolkit.} The finiteness of $\mathrm{Taxicab}(n)$ for all $n$ is true but its known proofs are non-elementary, running through the group law on the elliptic curve $x^3+y^3=N$: a rational point of infinite order generates infinitely many rational solutions, and clearing denominators of $n$ of them by a common cube deposits $n$ distinct integer representations onto one integer. The cube-scaling principle is the elementary shadow of this process.

\textbf{Growth is likely super-polynomial.} The floor $\mathrm{Taxicab}(n) > n^3$ is loose; empirical values grow far faster, consistent with $\log\mathrm{Taxicab}(n)/n\to\infty$.

\textbf{A cube-free reduction.} Corollary of Theorem~\ref{thm:scale2} gives the easy direction of a conjectural reduction of representation-counting to cube-free targets; the reverse inclusion is open.

\section{Future work}

Formalize the elliptic-curve existence argument; prove a super-polynomial growth bound; settle the cube-free reduction; and extend to cabtaxi numbers (differences of cubes).

\section{Conclusion}

Representations are rigid, forcing a provable cubic floor $\mathrm{Taxicab}(n) > n^3$, and are multiplicatively transported by cube-scaling, which marks the exact frontier where elliptic curves become indispensable. The classical champions $1729$, $87{,}539{,}319$, and $6{,}963{,}472{,}309{,}248$ stand verified as genuine $2$-, $3$-, and $4$-fold sums of cubes.

