from typing import List, Tuple

def integer_cube_root(n: int) -> int:
    if n <= 0:
        return 0
    lo, hi = 0, 1
    while hi ** 3 <= n:
        hi *= 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def representations(N: int) -> List[Tuple[int, int]]:
    reps: List[Tuple[int, int]] = []
    a = 1
    while 2 * a ** 3 <= N:
        rem = N - a ** 3
        r = integer_cube_root(rem)
        if r ** 3 == rem and r >= a:
            reps.append((a, r))
        a += 1
    return reps

for N in (1729, 87539319, 6963472309248):
    print(N, representations(N))

