from typing import Dict, Tuple

def taxicab_search(k: int, L: int) -> Tuple[int, int]:
    counts: Dict[int, int] = {}
    for a in range(1, L + 1):
        a3 = a ** 3
        for b in range(a, L + 1):
            s = a3 + b ** 3
            counts[s] = counts.get(s, 0) + 1
    best = min((s for s, c in counts.items() if c >= k), default=-1)
    return best, counts.get(best, 0)

print(taxicab_search(2, 20))   # -> (1729, 2)
